/**
 * Who may do what — generated by hand from spec/01-crud-matrix.md
 * (references/uml-to-code-mapping.md section 6). Services call assertCan()
 * before doing anything; "own" rows are also filtered by borrowerId in queries.
 *
 * tests/integration/permissions.test.ts checks this table against the
 * transition table, so the two cannot drift apart.
 */
import type { Role } from "@/domain/context";
import { DomainError } from "@/domain/errors";

export const PERMISSIONS = {
  // Loan
  "loan.create": ["Borrower"],
  "loan.readOwn": ["Borrower"],
  "loan.readAll": ["Clerk", "Manager", "DeptHead"],
  "loan.withdraw": ["Borrower"], // own (T5, T6)
  "loan.review": ["Manager"], // T1
  "loan.approve": ["Manager", "DeptHead"], // T3 and internal approval (Approval C)
  "loan.reject": ["Manager", "DeptHead"], // T4 (Approval C)
  "loan.cancel": ["Manager"], // T11
  "loan.checkOut": ["Clerk"], // T7
  "loan.return": ["Clerk", "Manager"], // T9, T10 (+ LateFee U 登记已缴)
  "loan.runDailyChecks": ["Manager", "System"], // T8, BR-09 (FUS6 AC3)
  // Agreement
  "agreement.sign": ["Borrower"], // own
  // Equipment
  "equipment.read": ["Borrower", "Clerk", "Manager", "DeptHead"],
  // AuditEntry
  "audit.read": ["Manager", "DeptHead"],
  // Person
  "person.updateOwnContact": ["Borrower"],
  "phone.readFull": ["Clerk", "Manager"], // C-01, NFUS3
  // Statistics and settings
  "stats.read": ["DeptHead"], // BR-13
  "settings.update": ["Manager"], // NFUS6 AC2
} as const satisfies Record<string, readonly Role[]>;

export type Operation = keyof typeof PERMISSIONS;

export const can = (role: Role, op: Operation) => (PERMISSIONS[op] as readonly Role[]).includes(role);

export function assertCan(role: Role, op: Operation) {
  if (!can(role, op)) throw new DomainError("FORBIDDEN", "你的角色不能进行这项操作。", "NFUS1");
}
